// The bundled Lucide icon subset (public/renderer/icons.js, generated by scripts/build-icons.ts).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { ICONS, ICON_ALIASES, ICON_NAMES, iconData } from "../public/renderer/icons.js";

const TAGS = new Set(["path", "circle", "rect", "line", "polyline", "polygon", "ellipse"]);
const ATTRS = new Set(["d", "cx", "cy", "r", "rx", "ry", "x", "y", "x1", "y1", "x2", "y2", "width", "height", "points"]);

test("every curated name and alias resolves", () => {
  assert.ok(ICON_NAMES.length >= 90);
  for (const name of ICON_NAMES) assert.ok(iconData(name), name);
  for (const [alias, target] of Object.entries(ICON_ALIASES)) {
    assert.ok(ICON_NAMES.includes(target), `${alias} -> ${target}`);
    assert.equal(iconData(alias), ICONS[target], alias);
  }
});

test("names are matched case-insensitively and tolerate spaces and underscores", () => {
  assert.equal(iconData("Home"), ICONS["home"]);
  assert.equal(iconData("BAR_CHART 3".replace(" ", "-")), ICONS["bar-chart-3"]);
  assert.equal(iconData("Money Bag"), ICONS["wallet"]);
  assert.equal(iconData("  CHART "), ICONS["bar-chart-3"]);
});

test("unknown, empty and prototype names resolve to null", () => {
  for (const bad of ["nope", "", "__proto__", "constructor", "toString", undefined, null]) assert.equal(iconData(bad as any), null, String(bad));
});

test("stored elements are geometry only", () => {
  for (const [name, els] of Object.entries(ICONS)) {
    assert.ok(els.length > 0, name);
    for (const [tag, attrs] of els) {
      assert.ok(TAGS.has(tag), `${name}: <${tag}>`);
      for (const key of Object.keys(attrs)) {
        assert.ok(ATTRS.has(key), `${name}: ${key}`);
        assert.ok(!/^on/i.test(key) && !/href/i.test(key), `${name}: ${key}`);
      }
    }
  }
});

test("icons.js is import-free, sorted, and carries the Lucide ISC notice", () => {
  const src = readFileSync(new URL("../public/renderer/icons.js", import.meta.url), "utf8");
  assert.match(src, /ISC/);
  assert.match(src, /Lucide/);
  assert.match(src, /do not edit/);
  assert.doesNotMatch(src, /^\s*import\s/m);
  assert.deepEqual(ICON_NAMES, [...ICON_NAMES].sort());
});

// ---- Bundled stock images (public/renderer/images, public/renderer/images.js) ----
import { existsSync, statSync } from "node:fs";
import { IMAGES, IMAGE_SUBJECTS, resolveImage } from "../public/renderer/images.js";
import { checkImages, readWebpSize } from "../scripts/check-images.ts";

const IMG_DIR = new URL("../public/renderer/images/", import.meta.url);

test("40 images across the six subjects", () => {
  assert.deepEqual([...IMAGE_SUBJECTS], ["food", "places", "people", "products", "workspaces", "abstract"]);
  assert.equal(IMAGES.length, 40);
  const counts = { food: 7, places: 7, people: 7, products: 7, workspaces: 7, abstract: 5 } as Record<string, number>;
  for (const s of IMAGE_SUBJECTS) assert.equal(IMAGES.filter((i) => i.subject === s).length, counts[s], s);
});

test("every image file is a small WebP whose manifest size matches", () => {
  let total = 0;
  for (const img of IMAGES) {
    assert.match(img.file, /^[a-z]+-\d+\.webp$/);
    assert.ok(img.file.startsWith(`${img.subject}-`), img.file);
    const path = new URL(img.file, IMG_DIR);
    assert.ok(existsSync(path), img.file);
    const bytes = readFileSync(path);
    total += bytes.length;
    assert.ok(bytes.length <= 80 * 1024, `${img.file} is ${bytes.length} bytes`);
    const size = readWebpSize(bytes);
    assert.ok(size, `${img.file} is not WebP`);
    assert.ok(Math.max(size.width, size.height) <= 800, `${img.file} ${size.width}x${size.height}`);
    assert.deepEqual([img.width, img.height], [size.width, size.height], img.file);
    assert.ok(statSync(path).isFile());
  }
  assert.ok(total <= 3 * 1024 * 1024, `total ${total}`);
});

test("every image names its caption, author, source and license", () => {
  for (const img of IMAGES) {
    assert.ok(img.caption && img.caption.split(/\s+/).length <= 5, `${img.file} caption`);
    assert.ok(img.author, `${img.file} author`);
    assert.match(img.source, /^https:\/\/(www\.)?(unsplash|pexels)\.com\//, img.file);
    assert.ok(["Unsplash License", "Pexels License"].includes(img.license), img.file);
  }
});

test("LICENSES.md lists every file and the check script finds no problems", () => {
  const md = readFileSync(new URL("LICENSES.md", IMG_DIR), "utf8");
  for (const img of IMAGES) assert.ok(md.includes(img.file) && md.includes(img.source), img.file);
  assert.deepEqual(checkImages(), []);
});

test("resolveImage: exact name, subject by node id, else null", () => {
  assert.equal(resolveImage("food-3", "x")?.file, "food-3.webp");
  const a = resolveImage("food", "node-a");
  assert.ok(a && a.file.startsWith("food-"));
  assert.deepEqual(resolveImage("food", "node-a"), a);
  assert.equal(resolveImage("pizza", "a"), null);
  assert.equal(resolveImage("food-99", "a"), null);
  assert.equal(resolveImage(undefined, "a"), null);
  assert.equal(resolveImage(42, "a"), null);
  const seen = new Set<string>();
  for (let i = 0; i < 60; i++) seen.add(resolveImage("places", `n${i}`)!.file);
  assert.ok(seen.size > 3);
  assert.equal(resolveImage("abstract", "q")!.file.startsWith("abstract-"), true);
});

test("images.js is import-free", () => {
  const src = readFileSync(new URL("../public/renderer/images.js", import.meta.url), "utf8");
  assert.doesNotMatch(src, /^\s*import\s/m);
});
